# -*- coding: utf-8 -*-
# PTX implementation of a fp16 1‑D convolution (no padding) for SM80 (A100)

PTX_SOURCE = r'''
.version 7.2
.target sm_80
.address_size 64

.visible .entry conv1d_fp16(
    .param .u64   input_ptr,
    .param .u64   weight_ptr,
    .param .u64   bias_ptr,
    .param .u64   output_ptr,
    .param .u32   N,
    .param .u32   C_in,
    .param .u32   C_out,
    .param .u32   L_in,
    .param .u32   L_out,
    .param .u32   K,
    .param .u32   stride,
    .param .u32   dilation,
    .param .u32   total_threads
)
{
    // ------------------------------------------------------------
    // Register declarations
    // ------------------------------------------------------------
    .reg .pred   %p0;
    .reg .u32    %tid, %bid, %gid;
    .reg .u64    %inp_ptr, %wgt_ptr, %bias_ptr, %out_ptr;
    .reg .u32    %n, %co, %lo, %rem, %tmp_u32;
    .reg .u64    %offset64;
    .reg .u32    %ci, %k;
    .reg .f32    %acc, %in_f32, %w_f32, %b_f32;
    .reg .f16    %in_f16, %w_f16, %b_f16, %out_f16;
    .reg .u64    %addr;

    // ------------------------------------------------------------
    // Load kernel parameters
    // ------------------------------------------------------------
    ld.param.u64    %inp_ptr,    [input_ptr];
    ld.param.u64    %wgt_ptr,    [weight_ptr];
    ld.param.u64    %bias_ptr,   [bias_ptr];
    ld.param.u64    %out_ptr,    [output_ptr];
    ld.param.u32    %N,          [N];
    ld.param.u32    %C_in,       [C_in];
    ld.param.u32    %C_out,      [C_out];
    ld.param.u32    %L_in,       [L_in];
    ld.param.u32    %L_out,      [L_out];
    ld.param.u32    %K,          [K];
    ld.param.u32    %stride,     [stride];
    ld.param.u32    %dilation,   [dilation];
    ld.param.u32    %total_threads, [total_threads];

    // ------------------------------------------------------------
    // Compute global thread ID
    // ------------------------------------------------------------
    mov.u32 %tid,   %tid.x;
    mov.u32 %bid,   %ctaid.x;
    mad.lo.u32 %gid, %bid, %ntid.x, %tid;        // gid = blockIdx.x * blockDim.x + threadIdx.x

    // ------------------------------------------------------------
    // Bounds check
    // ------------------------------------------------------------
    setp.ge.u32 %p0, %gid, %total_threads;
    @%p0 ret;

    // ------------------------------------------------------------
    // Decompose linear index into (n, co, lo)
    // ------------------------------------------------------------
    // tmp_u32 = C_out * L_out
    mul.lo.u32 %tmp_u32, %C_out, %L_out;

    // n = gid / (C_out * L_out)
    div.u32 %n, %gid, %tmp_u32;

    // rem = gid % (C_out * L_out)
    mul.lo.u32 %offset64, %n, %tmp_u32;
    sub.u32 %rem, %gid, %offset64;

    // co = rem / L_out
    div.u32 %co, %rem, %L_out;

    // lo = rem % L_out
    mul.lo.u32 %offset64, %co, %L_out;
    sub.u32 %lo, %rem, %offset64;

    // ------------------------------------------------------------
    // Initialize accumulator (FP32)
    // ------------------------------------------------------------
    mov.f32 %acc, 0f00000000;

    // ------------------------------------------------------------
    // Loop over input channels (ci) and kernel positions (k)
    // ------------------------------------------------------------
    mov.u32 %ci, 0;
LOOP_CI:
    setp.ge.u32 %p0, %ci, %C_in;
    @%p0 bra END_CI;

    mov.u32 %k, 0;
LOOP_K:
    setp.ge.u32 %p0, %k, %K;
    @%p0 bra END_K;

    // ----- compute input offset -----
    // base = n * C_in * L_in
    mul.lo.u32 %offset64, %n, %C_in;
    mul.lo.u32 %offset64, %offset64, %L_in;

    // add ci * L_in
    mul.lo.u32 %tmp_u32, %ci, %L_in;
    add.u32 %offset64, %offset64, %tmp_u32;

    // add (lo * stride + k * dilation)
    mul.lo.u32 %tmp_u32, %lo, %stride;
    mul.lo.u32 %tmp_u32, %tmp_u32, 1;          // keep in %tmp_u32
    mad.lo.u32 %tmp_u32, %k, %dilation, %tmp_u32; // tmp = lo*stride + k*dilation
    add.u32 %offset64, %offset64, %tmp_u32;

    // convert to byte offset (fp16 = 2 bytes)
    mul.wide.u32 %addr, %offset64, 2;
    add.u64 %addr, %inp_ptr, %addr;
    ld.global.f16 %in_f16, [%addr];

    // ----- compute weight offset -----
    // weight layout: (C_out, C_in, K) => index = ((co * C_in + ci) * K) + k
    mul.lo.u32 %offset64, %co, %C_in;
    mul.lo.u32 %offset64, %offset64, %K;
    mul.lo.u32 %tmp_u32, %ci, %K;
    add.u32 %offset64, %offset64, %tmp_u32;
    add.u32 %offset64, %offset64, %k;

    mul.wide.u32 %addr, %offset64, 2;
    add.u64 %addr, %wgt_ptr, %addr;
    ld.global.f16 %w_f16, [%addr];

    // ----- multiply‑accumulate (FP16 -> FP32) -----
    cvt.f32.f16 %in_f32, %in_f16;
    cvt.f32.f16 %w_f32,  %w_f16;
    fma.rn.f32 %acc, %in_f32, %w_f32, %acc;

    // ----- next k -----
    add.u32 %k, %k, 1;
    bra LOOP_K;
END_K:

    // ----- next ci -----
    add.u32 %ci, %ci, 1;
    bra LOOP_CI;
END_CI:

    // ------------------------------------------------------------
    // Add bias if provided (bias_ptr != 0)
    // ------------------------------------------------------------
    setp.ne.u64 %p0, %bias_ptr, 0;
    @%p0 {
        mul.wide.u32 %addr, %co, 2;          // bias is (C_out) fp16
        add.u64 %addr, %bias_ptr, %addr;
        ld.global.f16 %b_f16, [%addr];
        cvt.f32.f16 %b_f32, %b_f16;
        add.f32 %acc, %acc, %b_f32;
    }

    // ------------------------------------------------------------
    // Convert accumulator back to fp16 and store
    // ------------------------------------------------------------
    cvt.rn.f16.f32 %out_f16, %acc;

    // output layout: (N, C_out, L_out) => index = ((n * C_out + co) * L_out) + lo
    mul.lo.u32 %offset64, %n, %C_out;
    mul.lo.u32 %offset64, %offset64, %L_out;
    mul.lo.u32 %tmp_u32, %co, %L_out;
    add.u32 %offset64, %offset64, %tmp_u32;
    add.u32 %offset64, %offset64, %lo;

    mul.wide.u32 %addr, %offset64, 2;
    add.u64 %addr, %out_ptr, %addr;
    st.global.f16 [%addr], %out_f16;

    ret;
}
'''

class ModelNew:
    def __init__(self):
        # Load PTX module using the provided harness
        self.module = ptx_load(PTX_SOURCE)

    def __call__(self, inputs, init_params):
        """
        inputs: [x, weight, bias]   # bias may be None
        init_params: [in_channels, out_channels, kernel_size, stride, dilation]
        Returns: output tensor (fp16)
        """
        import torch

        x, weight = inputs[0], inputs[1]
        bias = inputs[2] if len(inputs) > 2 else None

        in_channels, out_channels, kernel_size, stride, dilation = init_params
        batch, _, length = x.shape

        # Compute output length (same formula as torch.nn.Conv1d with padding=0)
        L_out = (length - dilation * (kernel_size - 1) - 1) // stride + 1

        # Allocate output tensor
        out = torch.empty((batch, out_channels, L_out), dtype=torch.float16, device=x.device)

        total_threads = batch * out_channels * L_out
        block = (256, 1, 1)
        grid = ((total_threads + block[0] - 1) // block[0], 1, 1)

        # Prepare argument list for the PTX kernel
        args = [
            x.data_ptr(),
            weight.data_ptr(),
            bias.data_ptr() if bias is not None else 0,
            out.data_ptr(),
            batch,
            in_channels,
            out_channels,
            length,
            L_out,
            kernel_size,
            stride,
            dilation,
            total_threads,
        ]

        # Launch the kernel
        ptx_launch(self.module, "conv1d_fp16", grid, block, args)

        return out
